<?php require __DIR__.'/config/config.php'; require __DIR__.'/config/helpers.php'; if(current_user()) redirect(dashboard_url()); verify_csrf(); $error=''; $role=($_GET['role']??$_POST['role']??'client')==='hotelier'?'hotelier':'client'; if($_SERVER['REQUEST_METHOD']==='POST'){ $nom=trim($_POST['nom']??'');$prenom=trim($_POST['prenom']??'');$email=trim($_POST['email']??'');$tel=trim($_POST['telephone']??'');$pass=$_POST['password']??'';$confirm=$_POST['confirmation']??''; $hotel=trim($_POST['hotel']??'');$ville=trim($_POST['ville']??''); if(!$nom||!$prenom||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||$pass!==$confirm||!$tel){$error='Vérifiez les champs. Le mot de passe doit contenir au moins 8 caractères et les deux mots de passe doivent correspondre.';} elseif($role==='hotelier'&&(!$hotel||!$ville)){$error='Le nom de l’hôtel et la ville sont obligatoires.';} else {try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO users(nom,prenom,email,telephone,password,role) VALUES(?,?,?,?,?,?)');$q->execute([$nom,$prenom,$email,$tel,password_hash($pass,PASSWORD_DEFAULT),$role]);$uid=(int)$pdo->lastInsertId();if($role==='hotelier'){$q=$pdo->prepare("INSERT INTO hotels(user_id,nom,ville,telephone,email,statut) VALUES(?,?,?,?,?,'attente')");$q->execute([$uid,$hotel,$ville,$tel,$email]);}$pdo->commit();flash('success',$role==='hotelier'?'Compte créé. Votre hôtel est en attente de validation.':'Compte créé. Vous pouvez vous connecter.');redirect('login.php');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getCode()==='23000'?'Cette adresse email est déjà utilisée.':'Une erreur est survenue pendant l’inscription.';}}} $pageTitle='Créer un compte';require __DIR__.'/includes/header.php';?><section class="auth-wrap"><form class="auth-card" method="post"><?=csrf_field()?><span class="eyebrow">REJOIGNEZ HOTELCONNECT</span><h1><?= $role==='hotelier'?'Inscrire mon hôtel':'Créer un compte' ?></h1><p><?= $role==='hotelier'?'Présentez votre établissement aux voyageurs.':'Trouvez et réservez votre prochain séjour.' ?></p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><input type="hidden" name="role" value="<?=e($role)?>"><div class="row"><div class="col-6 mb-3"><label class="form-label">Nom</label><input class="form-control" name="nom" required value="<?=e($_POST['nom']??'')?>"></div><div class="col-6 mb-3"><label class="form-label">Prénom</label><input class="form-control" name="prenom" required value="<?=e($_POST['prenom']??'')?>"></div></div><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required value="<?=e($_POST['email']??'')?>"><label class="form-label">Téléphone</label><input class="form-control mb-3" name="telephone" required value="<?=e($_POST['telephone']??'')?>"><?php if($role==='hotelier'):?><label class="form-label">Nom de l’hôtel</label><input class="form-control mb-3" name="hotel" required value="<?=e($_POST['hotel']??'')?>"><label class="form-label">Ville</label><input class="form-control mb-3" name="ville" required value="<?=e($_POST['ville']??'')?>"><?php endif;?><label class="form-label">Mot de passe (8 caractères minimum)</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><label class="form-label">Confirmer le mot de passe</label><input class="form-control mb-3" type="password" name="confirmation" minlength="8" required><button class="btn btn-primary">Créer mon compte →</button><p class="auth-switch">Déjà inscrit ? <a class="text-link" href="login.php">Se connecter</a></p></form></section><?php require __DIR__.'/includes/footer.php';?>